'use strict';
const assert = require('node:assert/strict'), fs = require('node:fs'), vm = require('node:vm'), path = require('node:path');
const makeDOM = require('./legacy_oao_dom');
const source = name => fs.readFileSync(path.join(process.argv[2], name), 'utf8');
const dom = makeDOM(), doc = dom.doc, proto = Object.getPrototypeOf(dom.create('div'));
doc.querySelectorAll = selector => doc.body.querySelectorAll(selector);
const setAttribute = proto.setAttribute;
proto.setAttribute = function(k,v) { setAttribute.call(this,k,v); if(k.startsWith('data-')) this.dataset[k.slice(5).replace(/-([a-z])/g,(_,c)=>c.toUpperCase())]=String(v); };
Object.defineProperty(proto,'open',{get(){return this.hasAttribute('open');},set(v){v?this.setAttribute('open',''):this.removeAttribute('open');}});
['queue-stages','queue-overview','queue-freshness','queue-gov','queue-gov-msg'].forEach(id=>{const el=dom.create('div');el.id=id;doc.body.appendChild(el);});
const get=id=>doc.getElementById(id), requests=[], messages=[];
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const c=vm.createContext({console,document:doc,Date,Set,Map,WeakMap,esc,fmtDuration:v=>v+'ns',currentModule:'queues',currentSite:null,openTable:(...args)=>requests.push(args)});
vm.runInContext(source('workbench.js'),c);vm.runInContext(source('queue-governance.js'),c);
const stage=(site,n)=>({site,stage:'detail',queue:{queue_len:n,in_progress:n+2,completed:8,failed:1,submitted:15},workers:{0:{TotalTasks:9,FailedTasks:1,TotalTime:50}},global:{AvgTime:5}});
const data={instance_id:'one',generated_at:new Date().toISOString(),breakers:[{site:'a',stage:'detail',paused:true,source:'breaker',reason:'<script>bad</script>'}],stages:{'a:detail':stage('a',3),'b:detail':stage('b',7)}};
assert.equal(c.buildQueueGovernance(data,null).queued,10);assert.equal(c.buildQueueGovernance(data,null).unfinished,14);
assert.equal(c.buildQueueGovernance(data,'a').rows.length,1);assert.equal(c.buildQueueGovernance(data,'b').rows[0].pauses.length,0);
assert.equal(c.buildQueueGovernance({stages:{old:{site:'a'}}},'a').queued,null);
assert.equal(c.buildQueueGovernance({},null).unfinished,null);
c.renderQueueGovernance(data,null);
assert.equal(get('queue-stages').querySelectorAll('details').length,2);
assert.equal(get('queue-stages').querySelectorAll('script').length,0);
assert.match(get('queue-stages').textContent,/<script>bad/);
get('queue-stages').querySelector('details').open=true;
c.renderQueueGovernance(data,null);assert.equal(get('queue-stages').querySelector('details').open,true,'polling closed inspected stage');
get('queue-stages').querySelector('[data-queue-tasks]').onclick();assert.equal(requests[0][3].site,'a');assert.equal(requests[0][3].stage,'detail');
c.renderQueueGovernance(data,'b');assert.equal(get('queue-stages').querySelector('details').open,false,'same stage name leaked expansion across sites');
c.renderQueueGovernance({...data,instance_id:'two'},null);assert.equal(get('queue-stages').querySelector('details').open,false);
c.setQueueGovernanceConnection(false,'断开');assert.match(get('queue-freshness').textContent,/连接异常/);
c.renderQueueGovernance({...data,generated_at:'2020-01-01T00:00:00Z'},null);assert.match(get('queue-freshness').textContent,/超过 30 秒/);
c.resetQueueGovernance();assert.equal(get('queue-stages').textContent,'');assert.equal(get('queue-gov').textContent,'');assert.doesNotMatch(get('queue-freshness').textContent,/2020/);
c.renderQueueGovernance({},null);assert.match(get('queue-stages').textContent,/不代表数据库没有/);
const mo=source('mo.js'),start=mo.indexOf('    var queueFlights ='),end=mo.indexOf('    /* ============ 站点 Tab',start);
vm.runInContext(mo.slice(start,end),c);
const deferred=()=>{let resolve;const promise=new Promise(r=>resolve=r);return {promise,resolve};};
const tick=()=>new Promise(r=>setImmediate(r));
let epoch=0, confirm, response, posted=0;
c.queueMeta=n=>n==='error'?{label:'错误队列',url:'/error',key:'processed',done:'重投'}:null;
c.captureMonitorView=()=>{let e=epoch;return ()=>e===epoch&&c.currentModule==='queues';};
c.Dialog={confirm:opts=>{assert.match(opts.body,/全部站点/);confirm=deferred();return confirm.promise;}};
c.apiRequest=(url,opts)=>{assert.equal(opts.method,'POST');assert.equal(typeof opts.current,'function');posted++;response=deferred();return response.promise;};
c.Toast={ok:m=>messages.push(m),err:m=>messages.push(m)};c.fetchData=()=>messages.push('refresh');
(async()=>{
 let p=c.triggerQueue('error');await c.triggerQueue('error');assert.equal(posted,0);confirm.resolve(false);await p;assert.equal(posted,0);
 p=c.triggerQueue('error');epoch++;confirm.resolve(true);await p;assert.equal(posted,0,'stale confirmation dispatched');
 p=c.triggerQueue('error');confirm.resolve(true);await tick();assert.equal(posted,1);await c.triggerQueue('error');assert.equal(posted,1);
 const body=deferred();response.resolve({ok:true,json:()=>body.promise});await tick();epoch++;body.resolve({processed:3});await p;assert.equal(messages.length,0,'old identity body updated UI');
 p=c.triggerQueue('error');confirm.resolve(true);await tick();c.currentModule='dashboard';response.resolve({ok:true,json:async()=>({processed:4})});await p;assert.equal(messages.length,0,'old view response updated UI');
 c.currentModule='queues';p=c.triggerQueue('error');confirm.resolve(true);await tick();response.resolve({ok:true,json:async()=>({processed:2})});await p;assert.match(messages[0],/2 个任务（全部站点）/);assert.equal(messages[1],'refresh');
 assert.equal(c.queueFlights.error,undefined);
 console.log('PASS queue governance scope, unknowns, escaping, details, task filters, identity reset and manual-operation races');
})().catch(e=>{console.error(e);process.exitCode=1;});
